// Accepts a YouTube channel, playlist or video link from the form and labels its type.
const f = $('Form: add a channel, playlist or video').first().json;
const link = String(f.Link || '').trim();
const isYouTube = /^(https?:\/\/)?(www\.|m\.)?(youtube\.com|youtu\.be)\//i.test(link) || /^@[\w.-]+$/.test(link);
if (!isYouTube) throw new Error('Not a YouTube link: ' + link);
return [{ json: { Link: link, Label: String(f.Label || '').trim(), 'Added at': new Date().toISOString() } }];

// Sorts the Sources tab into channel, playlist and video links for the actor. Rows with Active = no are skipped.
const s = $('Settings').first().json;
const rows = $input.all().map((i) => i.json);
const kinds = { channelUrls: new Set(), playlistUrls: new Set(), videoUrls: new Set() };
for (const r of rows) {
  const link = String(r.Link || '').trim();
  if (!link || String(r.Active || '').trim().toLowerCase() === 'no') continue;
  if (/[?&]v=|youtu\.be\/|\/shorts\/|\/live\/|\/embed\/|^[\w-]{11}$/.test(link)) kinds.videoUrls.add(link);
  else if (/[?&]list=/.test(link)) kinds.playlistUrls.add(link);
  else kinds.channelUrls.add(link);
}
const total = kinds.channelUrls.size + kinds.playlistUrls.size + kinds.videoUrls.size;
if (!total) throw new Error('The Sources tab has no links. Add a channel, playlist or video link under the Link header.');
return [{ json: {
  actorInput: {
    channelUrls: [...kinds.channelUrls],
    playlistUrls: [...kinds.playlistUrls],
    videoUrls: [...kinds.videoUrls],
    maxVideosPerSource: Number(s.maxVideosPerSource) || 5,
    maxItems: Math.min(Number(s.maxItemsPerRun) || 50, 500),
    language: s.language || 'en',
    onlyNewVideos: s.onlyNewVideos !== false,
    stateKey: s.stateKey || 'research-desk',
    outputFormats: ['text', 'segments'],
  },
  maxCostPerRunUsd: Math.max(Number(s.maxCostPerRunUsd) || 0.2, 0.01),
  sources: total,
} }];

// One row per delivered video. The transcript gets a [m:ss] mark about every minute.
// Google Sheets holds at most 50,000 characters in a cell, so longer text is cut and flagged.
const LIMIT = 49000;
const clock = (t) => { t = Math.floor(t || 0); const h = Math.floor(t / 3600), m = Math.floor((t % 3600) / 60), x = String(t % 60).padStart(2, '0'); return h ? h + ':' + String(m).padStart(2, '0') + ':' + x : m + ':' + x; };
const fetchedAt = new Date().toISOString();
const rows = [];
for (const { json: v } of $input.all()) {
  if (!v.video_id) continue;
  let marked = '';
  let next = 0;
  for (const seg of v.segments || []) {
    if (seg.start >= next) { marked += (marked ? '\n' : '') + '[' + clock(seg.start) + '] '; next = Math.floor(seg.start / 60) * 60 + 60; }
    else marked += ' ';
    marked += String(seg.text || '').replace(/\s+/g, ' ').trim();
  }
  if (!marked) marked = v.transcript_text || '';
  rows.push({ json: {
    'Video ID': v.video_id,
    'Video URL': v.video_url,
    Title: v.title || '',
    Channel: v.channel || '',
    Published: v.published_at ? String(v.published_at).slice(0, 10) : '',
    'Length (min)': v.duration_seconds ? Math.round(v.duration_seconds / 60) : '',
    Language: v.language || '',
    'Auto captions': v.is_auto_generated === true,
    Views: v.view_count ?? '',
    Likes: v.like_count ?? '',
    Words: v.word_count ?? '',
    Chapters: (v.chapters || []).map((c) => '[' + clock(c.start_seconds) + '] ' + c.title).join('\n'),
    Summary: '', 'Key points': '', Topics: '', 'Worth watching': '',
    Transcript: marked.length > LIMIT ? marked.slice(0, LIMIT) : marked,
    'Transcript cut': marked.length > LIMIT,
    'Fetched at': fetchedAt,
  } });
}
return rows;

// Builds one prompt per video. A transcript longer than maxAiCharacters is cut to evenly spaced
// one-minute parts (each keeps its [m:ss] mark), so the model sees the whole video, not only the start.
// It starts from the full transcript the actor returned, not the copy cut to fit a sheet cell.
const max = Number($('Settings').first().json.maxAiCharacters) || 40000;
const clock = (t) => { t = Math.floor(t || 0); const h = Math.floor(t / 3600), m = Math.floor((t % 3600) / 60), x = String(t % 60).padStart(2, '0'); return h ? h + ':' + String(m).padStart(2, '0') + ':' + x : m + ':' + x; };
const full = {};
for (const { json: v } of $('Download the transcripts').all()) {
  if (!v.video_id || !(v.segments || []).length) continue;
  const minutes = {};
  for (const seg of v.segments) { const k = Math.floor(seg.start / 60); minutes[k] = (minutes[k] ? minutes[k] + ' ' : '[' + clock(k * 60) + '] ') + String(seg.text || '').replace(/\s+/g, ' ').trim(); }
  full[v.video_id] = Object.keys(minutes).sort((a, b) => a - b).map((k) => minutes[k]).join('\n');
}
return $input.all().map(({ json: row }) => {
  const parts = String(full[row['Video ID']] || row.Transcript || '').split('\n');
  let text = parts.join('\n');
  let note = 'full transcript';
  if (text.length > max) {
    const avg = text.length / parts.length;
    const keep = Math.max(1, Math.floor(max / avg));
    const step = parts.length / keep;
    const picked = [];
    for (let i = 0; i < keep; i++) picked.push(parts[Math.floor(i * step)]);
    text = picked.join('\n').slice(0, max);
    note = 'evenly spaced parts of the transcript';
  }
  const prompt = [
    'You write research notes about one YouTube video. Use only the transcript below (' + note + ').',
    'Each [m:ss] mark is the time in the video where the following words are spoken.',
    'Reply with JSON only, no code fence, with these keys:',
    '"summary": exactly 5 short lines separated by \\n, plain facts from the video;',
    '"key_points": 3 to 6 objects {"time": "m:ss", "point": "..."}, each time copied from a mark at or before where the point is made;',
    '"topics": 3 to 8 short lowercase tags;',
    '"worth_watching": one sentence on who should watch it and why, or why it can be skipped.',
    '',
    'Title: ' + row.Title,
    'Channel: ' + row.Channel,
    row.Chapters ? 'Chapters:\n' + row.Chapters : 'Chapters: none',
    '',
    'Transcript:',
    text,
  ].join('\n');
  return { json: { ...row, prompt } };
});

// Reads the model's JSON and fills the four AI columns. Key points become links that open the video at that time.
const rows = $('Prepare transcript for the model').all();
const seconds = (t) => String(t || '0').split(':').reduce((a, b) => a * 60 + (Number(b) || 0), 0);
return $input.all().map((item, i) => {
  const { prompt, ...row } = rows[i].json;
  const raw = String(item.json.text || item.json.output || '');
  let ai = null;
  try { ai = JSON.parse(raw.replace(/^[^{]*/, '').replace(/[^}]*$/, '')); } catch (e) { ai = null; }
  if (!ai) return { json: { ...row, Summary: raw.slice(0, 2000), 'Worth watching': '(the model did not return JSON)' } };
  const base = 'https://youtu.be/' + row['Video ID'] + '?t=';
  return { json: { ...row,
    Summary: Array.isArray(ai.summary) ? ai.summary.join('\n') : String(ai.summary || ''),
    'Key points': (ai.key_points || []).map((k) => '[' + k.time + '] ' + k.point + ' ' + base + seconds(k.time)).join('\n'),
    Topics: (ai.topics || []).join(', '),
    'Worth watching': String(ai.worth_watching || ''),
  } };
});

// The run summary lists every video the actor could not read, with one of 9 reason codes.
const out = $('Read the run summary').first().json || {};
const tryLater = new Set(['live_now', 'upcoming', 'stream_processing', 'other']);
const checkedAt = new Date().toISOString();
return (out.failures || []).map((f) => ({ json: {
  'Video ID': f.video_id,
  'Video URL': f.video_url || ('https://www.youtube.com/watch?v=' + f.video_id),
  Title: f.title || '',
  'Reason code': f.reason_code || 'other',
  Error: f.error || '',
  'Try again later': tryLater.has(f.reason_code || 'other'),
  'Checked at': checkedAt,
} }));

// One Run log row per run: counts from the run summary and the exact charge from Apify's run record.
const run = $('Keep the finished run').first().json;
const out = $('Read the run summary').first().json || {};
const events = (run.pricingInfo && run.pricingInfo.pricingPerEvent && run.pricingInfo.pricingPerEvent.actorChargeEvents) || {};
let charged = 0;
for (const [name, count] of Object.entries(run.chargedEventCounts || {})) {
  const e = events[name] || {};
  const tiers = e.eventTieredPricingUsd || {};
  const price = e.eventPriceUsd ?? (tiers.FREE && tiers.FREE.tieredEventPriceUsd) ?? 0;
  charged += count * price;
}
const notes = [];
if (out.stopped_early) notes.push('stopped at the spend cap or item limit');
if ((out.not_processed || []).length) notes.push((out.not_processed || []).length + ' not processed (next run tries again)');
if ((out.warnings || []).length) notes.push(out.warnings.join('; '));
if (!out.requested && out.requested !== 0) notes.push('no run summary found');
return [{ json: {
  'Run at': new Date().toISOString(),
  Status: run.status,
  Sources: $('Build the actor input').first().json.sources,
  Requested: out.requested ?? '',
  Delivered: out.delivered ?? '',
  Failed: out.failed ?? '',
  'Charged (USD)': Math.round(charged * 100000) / 100000,
  'Apify run': 'https://console.apify.com/view/runs/' + run.id,
  Notes: notes.join('. '),
} }];

// The Apify call failed after 3 tries (bad token, no credit, Apify down). Log it and say so in the digest.
const err = $input.first().json.error || $input.first().json;
const message = typeof err === 'string' ? err : (err.message || JSON.stringify(err).slice(0, 500));
const inner = String(message).match(/message[^:]*:\s*[\\"]*([^"\\]+)/);
const short = (inner ? String(message).slice(0, 3) + ' ' + inner[1] : String(message)).slice(0, 300);
return [{ json: {
  'Run at': new Date().toISOString(),
  Status: 'NOT STARTED',
  Sources: $('Build the actor input').first().json.sources,
  Requested: '', Delivered: 0, Failed: '', 'Charged (USD)': 0, 'Apify run': '',
  Notes: 'Apify call failed: ' + short,
} }];

// One message for the whole run. Nothing is sent when there is nothing new.
const s = $('Settings').first().json;
if (s.sendDigest === false) return [];
const items = $input.all().map((i) => i.json);
const day = new Date().toISOString().slice(0, 10);
if (items.length && items[0].Status === 'NOT STARTED') {
  return [{ json: { subject: 'YouTube research desk: run failed ' + day, text: items[0].Notes + '\nCheck the Apify credential and your Apify credit, then run the workflow again.' } }];
}
const videos = items.filter((v) => v['Video ID']);
if (!videos.length) return [];
const lines = ['New videos today: ' + videos.length, ''];
for (const v of videos) {
  lines.push(v.Title + ' (' + v.Channel + ', ' + v['Length (min)'] + ' min)');
  lines.push(v['Video URL']);
  if (v.Summary) lines.push(v.Summary);
  if (v['Worth watching']) lines.push('Worth watching: ' + v['Worth watching']);
  lines.push('');
}
const failed = Number(($('Read the run summary').first().json || {}).failed) || 0;
if (failed) lines.push(failed + ' video(s) could not be read: see the Failed tab.');
return [{ json: { subject: 'YouTube research desk: ' + videos.length + ' new video(s) ' + day, text: lines.join('\n') } }];

// Plain keyword search over the transcripts in the sheet: scores each one-minute part by how many different
// question words it holds, keeps the best 6 parts, and builds a link that opens the video at that minute.
const question = String($('Chat: ask your channels').first().json.chatInput || '');
const stop = new Set('the and for with that this what which who how why when where does did are was were have has from into about your you they them their there then than but not can could would should will just also its it is in on of to a an or be by as at do i me my we our'.split(' '));
const stem = (w) => (w.length > 4 ? w.replace(/(ing|ed|es|s)$/, "") : w);
const words = [...new Set((question.toLowerCase().match(/[\p{L}\p{N}']+/gu) || []).filter((w) => w.length > 2 && !stop.has(w)).map(stem))];
const seconds = (t) => t.split(':').reduce((a, b) => a * 60 + Number(b), 0);
const parts = [];
for (const { json: v } of $input.all()) {
  if (!v['Video ID'] || !v.Transcript) continue;
  const lines = String(v.Transcript).split('\n').filter((l) => l.trim());
  lines.forEach((line, i) => {
    const m = line.match(/^\[(\d+(?::\d+){1,2})\]\s*(.*)$/);
    const text = m ? m[2] : line;
    // Whole words with a light stem. Score: how many different question words the part holds (counts most),
    // then up to 3 hits per word, so a word that fills the whole video cannot outrank the part that answers.
    const counts = {};
    for (const t of text.toLowerCase().match(/[\p{L}\p{N}']+/gu) || []) { const k = stem(t); counts[k] = (counts[k] || 0) + 1; }
    let distinct = 0, hits = 0;
    for (const w of words) if (counts[w]) { distinct++; hits += Math.min(counts[w], 3); }
    if (!distinct) return;
    const score = distinct * 10 + hits + (titleHit(v, words) ? 0.5 : 0);
    // Send this minute and the next one, so an answer that runs over the minute mark is not cut off.
    const next = lines[i + 1] ? String(lines[i + 1]).replace(/^\[[\d:]+\]\s*/, '') : '';
    parts.push({ score, title: v.Title, channel: v.Channel, at: m ? m[1] : '0:00', link: 'https://youtu.be/' + v['Video ID'] + '?t=' + (m ? seconds(m[1]) : 0), text: (text + ' ' + next).slice(0, 2400) });
  });
}
function titleHit(v, ws) { const t = String(v.Title || '').toLowerCase(); return ws.some((w) => t.includes(w)); }
parts.sort((a, b) => b.score - a.score);
const best = parts.slice(0, 6);
const context = best.length
  ? best.map((p, i) => '(' + (i + 1) + ') "' + p.title + '" by ' + p.channel + ' at ' + p.at + ' ' + p.link + '\n' + p.text).join('\n\n')
  : 'No passage in the collected transcripts matches the question.';
return [{ json: { question, context, found: best.length } }];

parameters.text:
=Answer the question using only the transcript passages below. They come from YouTube videos the user collected.
Cite every fact with the video title and its link, written as: "Title" at m:ss (link).
If the passages do not answer the question, say that the collected videos do not cover it and suggest a better search word. Keep it under 200 words.

Question: {{ $json.question }}

Passages:
{{ $json.context }}
